begin;
update private.admin_execution_environment_v1 set environment='DEVELOPMENT',configuration_reference='transactional-payment-fixture-0204',configured_at=clock_timestamp()where singleton;
set local search_path=public,extensions;
select no_plan();
grant usage on schema extensions to authenticated,service_role;
select ok(not has_function_privilege('anon','public.issue_client_commercial_document_v1(bigint,uuid,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.issue_client_commercial_document_v1(bigint,uuid,text,uuid)','EXECUTE'),'untrusted or automatic actors cannot manufacture a commercial document');
select ok(not has_table_privilege('authenticated','public.client_commercial_documents','INSERT')and not has_table_privilege('authenticated','public.client_billing_policy_versions','UPDATE'),'direct document/configuration mutations are denied');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select format('a2040000-0000-4000-8000-%s',lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','billing204-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values
('b2040000-0000-4000-8000-000000000001','Verified invoice buyer 204','Buyer 204','ACTIVE','a2040000-0000-4000-8000-000000000003'),
('b2040000-0000-4000-8000-000000000002','Other buyer 204','Other 204','ACTIVE','a2040000-0000-4000-8000-000000000004');
insert into public.organization_memberships(id,organization_id,user_id,status)values
('c2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001','a2040000-0000-4000-8000-000000000003','ACTIVE'),
('c2040000-0000-4000-8000-000000000002','b2040000-0000-4000-8000-000000000002','a2040000-0000-4000-8000-000000000004','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c2040000-0000-4000-8000-000000000001','CLIENT_OWNER'),('c2040000-0000-4000-8000-000000000002','CLIENT_OWNER');
insert into public.platform_user_roles(user_id,role_code)values('a2040000-0000-4000-8000-000000000001','FINANCE_MANAGER'),('a2040000-0000-4000-8000-000000000002','FINANCE_MANAGER');
-- Captures and verified buyer snapshots are the immutable upstream facts under test.
set local session_replication_role=replica;
insert into public.client_compliance_cases(id,organization_id,status,current_profile_version,verified_at,activated_at,created_by)values('d2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001','VERIFIED',1,now()-interval'10 days',now()-interval'10 days','a2040000-0000-4000-8000-000000000003');
insert into public.client_profile_versions(id,compliance_case_id,organization_id,version,profile_data,organization_snapshot,source_organization_row_version,created_by,created_at)values('d2040000-0000-4000-8000-000000000002','d2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001',1,'{"legal_form":"SARL","registered_address":{"line1":"Adresse de recette"},"registered_city":"Casablanca","if_number":"20400001","rc_number":"RC-204"}','{"legal_name":"Verified invoice buyer 204","country_code":"MA","identifiers":{"ICE":"204000000000001"}}',1,'a2040000-0000-4000-8000-000000000003',now()-interval'11 days');
insert into public.client_trials(organization_id,compliance_case_id,verified_profile_version,status,trial_started_at,trial_ends_at,activated_by)values('b2040000-0000-4000-8000-000000000001','d2040000-0000-4000-8000-000000000001',1,'TRIAL_ACTIVE',now()-interval'10 days',now()+interval'20 days','a2040000-0000-4000-8000-000000000001');
insert into public.client_profile_versions(id,compliance_case_id,organization_id,version,profile_data,organization_snapshot,source_organization_row_version,created_by,created_at)values('d2040000-0000-4000-8000-000000000003','d2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001',2,'{"legal_form":"SARL","registered_address":{"line1":"Nouvelle adresse de recette"},"registered_city":"Casablanca","if_number":"20400002","rc_number":"RC-204-V2"}','{"legal_name":"Verified buyer revision204","country_code":"MA","identifiers":{"ICE":"204000000000002"}}',2,'a2040000-0000-4000-8000-000000000003',now()-interval'30 minutes');
insert into public.client_identity_verification_history(compliance_case_id,organization_id,profile_version,verified_at,verified_by,source)values('d2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001',1,now()-interval'10 days','a2040000-0000-4000-8000-000000000001','HISTORICAL_TRIAL'),('d2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001',2,now()-interval'20 minutes','a2040000-0000-4000-8000-000000000001','COMPLIANCE_DECISION');
insert into public.subscription_payment_intents(id,organization_id,plan_version_id,billing_interval,gateway,provider_intent_id,amount_minor,currency,idempotency_key,request_hash,correlation_id,created_by)
select format('e2040000-0000-4000-8000-%s',lpad(i::text,12,'0'))::uuid,case when i=4 then'b2040000-0000-4000-8000-000000000002'::uuid else'b2040000-0000-4000-8000-000000000001'::uuid end,'e2040000-0000-4000-9000-000000000001','MONTHLY',case when i=3 then'DEMO'else'PAYPAL'end,'capture-intent-204-'||i,case when i=2 then 5 else 12000 end,'MAD','capture-204-'||i,repeat('a',64),'e2040000-0000-4000-9000-000000000002','a2040000-0000-4000-8000-000000000003'from generate_series(1,25)i;
insert into public.subscription_payment_events(payment_intent_id,organization_id,gateway,provider_event_id,provider_intent_id,event_type,amount_minor,currency,paid_at,payment_reference,payload_hash,signature_fingerprint,activation_result,correlation_id)
select id,organization_id,gateway,'capture-event-204-'||split_part(provider_intent_id,'-',4),provider_intent_id,'PAYMENT_SUCCEEDED',amount_minor,currency,case when split_part(provider_intent_id,'-',4)='25'then now()-interval'5 minutes'else now()-interval'1 hour'end,'CAPTURE-204-'||split_part(provider_intent_id,'-',4),repeat('a',64),repeat('a',64),'{}','e2040000-0000-4000-9000-000000000002'from public.subscription_payment_intents where provider_intent_id like'capture-intent-204-%';
insert into public.subscription_payment_adjustments(id,payment_event_id,gateway,provider_event_id,provider_adjustment_id,event_type,amount_minor,currency,payload_hash,signature_fingerprint,occurred_at,correlation_id)
select format('f2040000-0000-4000-8000-%s',lpad(x.i::text,12,'0'))::uuid,p.id,'PAYPAL','adjustment-event-204-'||x.i,'adjustment-resource-204-'||x.i,x.kind,x.amount,'MAD',repeat('a',64),repeat('a',64),now(),'e2040000-0000-4000-9000-000000000002'
from(values(1,'CAPTURE-204-1','REFUND_SUCCEEDED',2500),(2,'CAPTURE-204-1','PAYMENT_REVERSED',9500),(3,'CAPTURE-204-2','REFUND_SUCCEEDED',1),(4,'CAPTURE-204-2','REFUND_SUCCEEDED',4),(5,'CAPTURE-204-1','DISPUTE_OPENED',12000))x(i,reference,kind,amount)join public.subscription_payment_events p on p.payment_reference=x.reference;
set local session_replication_role=origin;
select set_config('test.capture1',(select id::text from public.subscription_payment_events where payment_reference='CAPTURE-204-1'),true);
select set_config('test.capture2',(select id::text from public.subscription_payment_events where payment_reference='CAPTURE-204-2'),true);
select set_config('test.capture3',(select id::text from public.subscription_payment_events where payment_reference='CAPTURE-204-3'),true);
select set_config('test.capture4',(select id::text from public.subscription_payment_events where payment_reference='CAPTURE-204-4'),true);
select set_config('test.policy_payload',jsonb_build_object('series_key','TEST_CLIENT_BILLING_204','version',1,'currency','MAD','tax_rate_bps',2000,'tax_label_fr','TVA de recette','tax_label_ar','ضريبة الاختبار','jurisdiction','MA-RECETTE','issuer',jsonb_build_object('legal_name','Émetteur de recette 204','legal_form','SARL','address','Adresse de recette 204','ice','999000000000204','if_number','99900204','rc_number','RC-TEST-204','contact_email','fiscal204@example.invalid'),'invoice_prefix','CI204','credit_prefix','CC204','invoice_start_number','41','credit_start_number','501','valid_from',(current_date-30)::text,'service_label_fr','Abonnement de recette','service_label_ar','اشتراك الاختبار','approval_reference','TEST-APPROVAL-204')::text,true);
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.create_client_billing_policy_v1(current_setting('test.policy_payload')::jsonb,'policy-create-204')$$,'42501','BILLING_POLICY_CREATE_DENIED','configuration requires finance MFA');
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.create_client_billing_policy_v1('{}','invalid-policy-204')$$,'22023','BILLING_POLICY_CONFIGURATION_REQUIRED','missing legal identity and fiscal data never become a policy');
select set_config('test.policy',(public.create_client_billing_policy_v1(current_setting('test.policy_payload')::jsonb,'policy-create-204')->>'policy_id'),true);
select lives_ok($$select public.create_client_billing_policy_v1(current_setting('test.policy_payload')::jsonb,'policy-create-204')$$,'policy creation replays without a second version');
select throws_ok(format('select public.approve_client_billing_policy_v1(%L::uuid,true,%L,%L)',current_setting('test.policy'),'Validation fiscale de recette','self-approve-204'),'42501','FOUR_EYES_REQUIRED','policy creator cannot approve their identity and fiscal rules');
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok(format('select public.issue_client_commercial_document_v1(%s,null,%L)',current_setting('test.capture1'),'issue-before-approval-204'),'55000','BILLING_POLICY_REQUIRED','an unapproved policy cannot issue an invoice');
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select lives_ok(format('select public.approve_client_billing_policy_v1(%L::uuid,true,%L,%L)',current_setting('test.policy'),'Validation fiscale de recette','approve-policy-204'),'independent finance approver publishes the immutable policy');
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select is((public.list_client_billable_sources_v1('b2040000-0000-4000-8000-000000000001')->>'total')::integer,24,'billable sources count every capture of the selected organization');
select is(jsonb_array_length(public.list_client_billable_sources_v1('b2040000-0000-4000-8000-000000000001')->'sources'),21,'billable source page has a sentinel after twenty captures');
select is((public.list_client_billable_sources_v1('b2040000-0000-4000-8000-000000000001','CAPTURE-204-1',1)->>'total')::integer,11,'payment search happens before pagination');
select is(jsonb_array_length(public.list_client_billable_sources_v1('b2040000-0000-4000-8000-000000000001','',2)->'sources'),4,'older captures remain reachable on the second page');
select is(jsonb_array_length(public.list_client_billable_sources_v1('b2040000-0000-4000-8000-000000000001','CAPTURE-204-1',1)#>'{sources,10,adjustments}'),2,'only confirmed refunds and reversals become credit note sources');
select throws_ok(format('select public.issue_scoped_client_commercial_document_v1(%L::uuid,%s,null,%L)','b2040000-0000-4000-8000-000000000001',current_setting('test.capture4'),'wrong-selected-source-204'),'42501','CLIENT_DOCUMENT_SOURCE_DENIED','selected organization must match the immutable captured source');
select set_config('test.invoice1',(public.issue_client_commercial_document_v1(current_setting('test.capture1')::bigint,null,'issue-invoice-204')->>'document_id'),true);
select is((select document_number from public.client_commercial_documents where id=current_setting('test.invoice1')::uuid),'CI204-'||extract(year from current_timestamp at time zone'Africa/Casablanca')::text||'-00000041','numbering begins at the approved starting number');
select is((select subtotal_minor::text||'/'||tax_minor::text||'/'||total_minor::text from public.client_commercial_documents where id=current_setting('test.invoice1')::uuid),'10000/2000/12000','invoice derives exact gross, tax and net from the capture');
select is((public.issue_client_commercial_document_v1(current_setting('test.capture1')::bigint,null,'issue-invoice-204')->>'document_id'),current_setting('test.invoice1'),'invoice command replays the same immutable document');
select is((public.issue_client_commercial_document_v1(current_setting('test.capture1')::bigint,null,'issue-invoice-other-key-204')->>'document_id'),current_setting('test.invoice1'),'one capture never gets duplicate invoices under another key');
select throws_ok(format('select public.issue_client_commercial_document_v1(%s,null,%L)',current_setting('test.capture2'),'issue-invoice-204'),'22000',null,'an idempotency key cannot switch to another captured payment');
select throws_ok(format('select public.issue_client_commercial_document_v1(%s,null,%L)',current_setting('test.capture3'),'issue-demo-invoice-204'),'55000','SIMULATED_PAYMENT_NOT_INVOICEABLE','DEMO payment cannot manufacture a fiscal invoice');
select throws_ok(format('select public.issue_client_commercial_document_v1(%s,%L::uuid,%L)',current_setting('test.capture1'),'f2040000-0000-4000-8000-000000000005','issue-dispute-credit-204'),'23514','CONFIRMED_CLIENT_REFUND_REQUIRED','a dispute does not masquerade as a confirmed credit note');
select set_config('test.credit1',(public.issue_client_commercial_document_v1(current_setting('test.capture1')::bigint,'f2040000-0000-4000-8000-000000000001','issue-credit-one-204')->>'document_id'),true);
select lives_ok(format('select public.issue_client_commercial_document_v1(%s,%L::uuid,%L)',current_setting('test.capture1'),'f2040000-0000-4000-8000-000000000002','issue-credit-two-204'),'reversal creates the remaining credit note');
select is((select sum(total_minor)::text||'/'||sum(tax_minor)::text from public.client_commercial_documents where original_invoice_id=current_setting('test.invoice1')::uuid),'12000/2000','full restitution credits the original gross and tax exactly');
select lives_ok(format('select public.issue_client_commercial_document_v1(%s,%L::uuid,%L)',current_setting('test.capture2'),'f2040000-0000-4000-8000-000000000003','issue-small-credit-one-204'),'credit note automatically obtains its required original invoice');
select lives_ok(format('select public.issue_client_commercial_document_v1(%s,%L::uuid,%L)',current_setting('test.capture2'),'f2040000-0000-4000-8000-000000000004','issue-small-credit-two-204'),'cumulative rounding handles the final small refund');
select is((select sum(tax_minor)::text from public.client_commercial_documents where payment_event_id=current_setting('test.capture2')::bigint and kind='CREDIT_NOTE'),(select tax_minor::text from public.client_commercial_documents where payment_event_id=current_setting('test.capture2')::bigint and kind='INVOICE'),'partial refunds never over-credit tax through independent rounding');
select throws_ok(format('update public.client_commercial_documents set total_minor=1 where id=%L::uuid',current_setting('test.invoice1')),'55000',null,'issued invoices are immutable');
select is((select document_snapshot#>>'{buyer,ice}'from public.client_commercial_documents where id=current_setting('test.invoice1')::uuid),'204000000000001','an old capture uses only the identity verified before that capture');
select lives_ok($$select public.issue_client_commercial_document_v1((select id from public.subscription_payment_events where payment_reference='CAPTURE-204-25'),null,'issue-after-revalidation-204')$$,'a capture after revalidation can issue from the newer historical identity');
select is((select document_snapshot#>>'{buyer,ice}'from public.client_commercial_documents where payment_event_id=(select id from public.subscription_payment_events where payment_reference='CAPTURE-204-25')and kind='INVOICE'),'204000000000002','new captures freeze the most recent identity verified at their capture time');
select is((select document_snapshot#>>'{buyer,ice}'from public.client_commercial_documents where id=current_setting('test.invoice1')::uuid),'204000000000001','new identity issuance never mutates an older invoice buyer snapshot');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.list_client_billable_sources_v1('b2040000-0000-4000-8000-000000000001')$$,'42501','CLIENT_BILLING_READ_DENIED','another tenant cannot read captured invoice sources');
select is((select count(*)::integer from public.client_commercial_documents where organization_id='b2040000-0000-4000-8000-000000000001'),0,'another tenant cannot list the documents');
select throws_ok(format('select public.authorize_client_commercial_document_v1(%L::uuid)',current_setting('test.invoice1')),'42501','CLIENT_BILLING_READ_DENIED','another tenant cannot authorize PDF access');
select throws_ok(format('select public.issue_client_commercial_document_v1(%s,null,%L)',current_setting('test.capture1'),'foreign-issue-204'),'42501','CLIENT_DOCUMENT_ISSUE_DENIED','another tenant cannot issue against the original capture');
select throws_ok(format('select public.issue_client_commercial_document_v1(%s,null,%L)',current_setting('test.capture4'),'missing-identity-204'),'55000','CLIENT_BILLING_IDENTITY_REQUIRED','missing verified buyer identity cannot be invented');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok(format('select public.complete_client_commercial_document_issue_v1(%L::uuid)',current_setting('test.invoice1')),'55000','CLIENT_BILLING_TRANSLATIONS_REQUIRED','readiness waits for both archived languages');
select set_config('test.invoice_hash',(select source_hash from public.client_commercial_documents where id=current_setting('test.invoice1')::uuid),true);
select lives_ok(format('select public.record_client_commercial_artifact_v1(%L::uuid,%L,%L,%L,100)',current_setting('test.invoice1'),'fr',current_setting('test.invoice_hash'),repeat('a',64)),'service records an exact authorized French artifact');
select throws_ok(format('select public.record_client_commercial_artifact_v1(%L::uuid,%L,%L,%L,100)',current_setting('test.invoice1'),'fr',current_setting('test.invoice_hash'),repeat('b',64)),'22000','CLIENT_BILLING_ARTIFACT_REPLAY_MISMATCH','archived bytes cannot change under the same document and language');
select lives_ok(format('select public.record_client_commercial_artifact_v1(%L::uuid,%L,%L,%L,100)',current_setting('test.invoice1'),'ar',current_setting('test.invoice_hash'),repeat('b',64)),'service records the Arabic artifact separately');
select lives_ok(format('select public.complete_client_commercial_document_issue_v1(%L::uuid)',current_setting('test.invoice1')),'both languages permit readiness');
select lives_ok(format('select public.complete_client_commercial_document_issue_v1(%L::uuid)',current_setting('test.invoice1')),'readiness replay is idempotent');
select is((select count(*)::integer from public.event_outbox where aggregate_id=current_setting('test.invoice1')and event_type='ClientCommercialDocumentReadyV1'),1,'one readiness outbox event exists');
select is((select count(*)::integer from public.audit_events where resource_id=current_setting('test.invoice1')and action='client.commercial_document.issued'),1,'one invoice issuance audit exists');
select is((select count(*)::integer from public.event_outbox where aggregate_id=current_setting('test.invoice1')and event_type='ClientCommercialDocumentIssuedV1'),1,'one durable rendering event exists');
select ok(not(select public from storage.buckets where id='client-billing-documents'),'commercial PDFs never use a public bucket');
select * from finish();
rollback;
